def _games_for_targets(
    games_payload,
    targets: set[str],
    week: int | None = None,
    scores_payload=None,
) -> list[dict]:
    out = []
    for g in transform.shape_games(games_payload, scores_payload=scores_payload):
        if week is not None and g.get("week") != week:
            continue
        if g["home_franchise_id"] in targets or g["away_franchise_id"] in targets:
            out.append(g)
    return out


# ---- ingest units -----------------------------------------------------------

def _ingest_dimensions_and_scope(conn, client, config, season, week=None):
    """Pull teams + games, upsert them, return the in-scope game dicts."""
    run_id = str(uuid.uuid4())
    started = datetime.now()

    teams_payload = client.get_teams(season)
    team_rows = transform.shape_teams(teams_payload)
    n = _upsert(conn, "teams", team_rows)
    _log(conn, run_id, started, season, week, "teams", len(team_rows), n, "success")

    games_payload = client.get_games(season)
    try:
        scores_payload = client.get_season_team_game_grades(season)
        _log(conn, run_id, started, season, week, "team_game_grades",
             len(transform._first_list(scores_payload, "games")), 0, "success")
    except Exception as e:
        scores_payload = None
        _log(conn, run_id, started, season, week, "team_game_grades",
             0, 0, "failed", str(e)[:200])
    game_rows = transform.shape_games(games_payload, scores_payload=scores_payload)
    n = _upsert(conn, "games", game_rows)
    _log(conn, run_id, started, season, week, "games", len(game_rows), n, "success")

    targets = _target_franchises(teams_payload, games_payload, config)
    return _games_for_targets(games_payload, targets, week=week, scores_payload=scores_payload)
def _ingest_extended_stats(conn, client, season):
    run_id = str(uuid.uuid4())
    started = datetime.now()
    total = 0
    for cat in EXTENDED_CATEGORIES:
        try:
            payload = client.get_extended_stats(season, cat)
        except Exception as e:
            _log(conn, run_id, started, season, None, f"stats:{cat}", 0, 0, "failed", str(e)[:200])
            continue
        rows = transform.shape_extended_stats(payload, cat)
        for r in rows:
            r["season"] = season
        total += _upsert(conn, "pff_stats", rows)
    _log(conn, run_id, started, season, None, "stats_extended", total, total, "success")
    return total



# ---- public modes -----------------------------------------------------------

def _run_one_season(conn, client, config, season, week=None, resume: bool = False) -> dict:
    eps = _endpoints(config)
    games = _ingest_dimensions_and_scope(conn, client, config, season, week=week)
    summary = {"season": season, "week": week, "in_scope_games": len(games)}
    if "grades" in eps:
        if resume and _grades_complete(conn, season, games):
            summary["grades"] = "skipped"
        else:
            summary["grades"] = _ingest_game_grades(conn, client, season, games)
    if "stats" in eps and week is None:  # extended stats are season-grain
        if resume and _stats_complete(conn, season):
            summary["stats"] = "skipped"
        else:
            summary["stats"] = _ingest_extended_stats(conn, client, season)
    if "premium" in eps:
        if resume and _premium_complete(conn, season):
            summary["premium"] = "skipped"
        else:
            summary["premium"] = _ingest_premium(conn, client, season, games)
    return summary


def run_backfill(
    conn: duckdb.DuckDBPyConnection,
