cd ~/DEV/Football/PFF_Position_Reports && cat > scripts/pff_weeks.py <<'EOF'
"""Which weeks the position pulls and models use. One home, so a checkpoint rebuild needs no code edits.

- Past seasons keep BASE_WEEKS: the pulls already on disk were made with it (the reason
  weeks 0 and 6 were left out was not recorded).
- The current season uses every week 1+ that has grade rows in the PFF_Data_Project DB.
  The Wednesday job (launchd com.keystone.pffpull) keeps that DB current.
- TEST_WEEKS: the 2 latest current-season weeks (on 2026-10-23 that was weeks 5 and 7).

Overrides (needed while the weekly job holds the DB write lock):
  PFF_CURRENT_WEEKS="1-12" or "1,2,3,4"     PFF_TEST_WEEKS="11,12"
"""
import os

BASE_WEEKS = {1, 2, 3, 4, 5, 7}
CURRENT_SEASON = 2026  # bump each new season, with config/pipeline.yaml in PFF_Data_Project


def _parse(text):
    out = set()
    for part in text.replace(" ", "").split(","):
        if "-" in part:
            a, b = part.split("-")
            out |= set(range(int(a), int(b) + 1))
        elif part:
            out.add(int(part))
    return out


def current_weeks():
    if os.environ.get("PFF_CURRENT_WEEKS"):
        return _parse(os.environ["PFF_CURRENT_WEEKS"])
    import duckdb
    path = os.environ.get("PFF_DB", os.path.expanduser("~/.local/share/pff-data/pff.db"))
    con = duckdb.connect(path, read_only=True)
    try:
        rows = con.execute(
            "SELECT DISTINCT g.week FROM games g JOIN pff_grades p USING (game_id) "
            "WHERE g.season = ? AND g.week >= 1", [CURRENT_SEASON]).fetchall()
    finally:
        con.close()
    return {int(r[0]) for r in rows}


def weeks_for(season):
    return current_weeks() if int(season) == CURRENT_SEASON else set(BASE_WEEKS)


def all_weeks():
    """Union for model filters. Past-season files only hold BASE_WEEKS, so the union adds no old rows."""
    return BASE_WEEKS | current_weeks()


def test_weeks():
    if os.environ.get("PFF_TEST_WEEKS"):
        return sorted(_parse(os.environ["PFF_TEST_WEEKS"]))
    return sorted(current_weeks())[-2:]


if __name__ == "__main__":
    assert _parse("1-3,7") == {1, 2, 3, 7} and _parse("5") == {5}
    print("current season", CURRENT_SEASON, "weeks", sorted(current_weeks()), "test weeks", test_weeks())
EOF
