import os, sys, io, csv, math
sys.path.insert(0, os.getcwd())
from dotenv import load_dotenv; load_dotenv(".env")
from src.ingest.pff_client import PFFClient
c = PFFClient(); c._ensure_token()
gid = 31272
pas = c.get_premium_game(str(gid), "passing"); pas = pas if isinstance(pas, list) else next(v for v in pas.values() if isinstance(v, list))
tg = [r for r in pas if r.get("target_player_id") and r.get("coverage_player_id")]
ev = c._get(f"/v1/tracking/ncaa/games/{gid}/play_events.json")["play_events"]
arr = {str(e["play_id"]): e["frame_number"] for e in ev if e["event_name"] == "pass_arrived"}
print("targeted passes", len(tg), "| with a pass_arrived frame", sum(str(r["play_id"]) in arr for r in tg))
r = c._session.get(f"{c.base_url}/v1/tracking/ncaa/games/{gid}/player_tracks.csv", headers={"Authorization": f"Bearer {c._token}", "Accept-Encoding": "gzip"}, timeout=300)
need = {(str(r_["play_id"]), arr.get(str(r_["play_id"]))) for r_ in tg}
pos = {}
for row in csv.DictReader(io.StringIO(r.text)):
    k = (row["play_id"], int(row["frame_number"]))
    if (row["play_id"], int(row["frame_number"])) in {(p, f) for p, f in need if f is not None} if False else k[0] in arr and k[1] == arr[k[0]]:
        pos[(row["play_id"], row["player_id"])] = (float(row["abs_path_x"]), float(row["abs_path_y"]))
